    errorFallback: "ਕੁਝ ਗੜਬੜ ਹੋ ਗਈ। ਇੱਕ ਵਾਰ ਫਿਰ ਕੋਸ਼ਿਸ਼ ਕਰੋਗੇ?",
    "error.not_configured": "ਜੱਜ ਹਾਲੇ ਸੈੱਟ ਨਹੀਂ ਹੋਇਆ। ਥੋੜ੍ਹੀ ਦੇਰ ਬਾਅਦ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "error.quota": "ਜੱਜਾਂ ਦਾ AI ਕੋਟਾ ਹਾਲ ਦੀ ਘੜੀ ਮੁੱਕ ਗਿਆ ਹੈ। ਕੁਝ ਮਿੰਟਾਂ ਬਾਅਦ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "error.unavailable": "ਇਸ ਵੇਲੇ ਜੱਜਾਂ ਤੱਕ ਪਹੁੰਚ ਨਹੀਂ ਹੋ ਰਹੀ। ਇੱਕ ਮਿੰਟ ਰੁਕ ਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "error.too_short": "ਇਹ ਤਾਂ ਬਹੁਤ ਘੱਟ ਹੈ। ਬਹਿਸ ਬਾਰੇ ਕੁਝ ਹੋਰ ਦੱਸੋ।",
    "error.too_long": "ਇਹ ਤਾਂ ਬਹੁਤ ਲੰਮਾ ਹੋ ਗਿਆ! 6000 ਅੱਖਰਾਂ ਤੋਂ ਘੱਟ ਰੱਖੋ।",
    "error.invalid": "ਇਹ ਬੇਨਤੀ ਠੀਕ ਨਹੀਂ ਲੱਗੀ।",
    "error.rate_limited": "ਆਰਡਰ, ਆਰਡਰ! ਹਾਲ ਦੀ ਘੜੀ ਤੁਹਾਡੀ ਹੱਦ ਪੂਰੀ ਹੋ ਗਈ ਹੈ। {wait} ਰੁਕ ਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "error.daily_cap": "ਅੱਜ ਲਈ ਅਦਾਲਤ ਬੰਦ। ਜਿੰਨੀਆਂ ਬਹਿਸਾਂ ਸੁਣ ਸਕਦੀ ਸੀ, ਸੁਣ ਲਈਆਂ। ਬੱਸ {wait} ਹੋਰ, ਫਿਰ ਹਾਜ਼ਰ।",
    "error.captcha_failed": "ਸਾਨੂੰ ਪੱਕਾ ਨਹੀਂ ਹੋ ਸਕਿਆ ਕਿ ਤੁਸੀਂ ਇਨਸਾਨ ਹੋ। ਜਾਂਚ ਦੁਬਾਰਾ ਕਰੋ, ਫਿਰ ਭੇਜੋ।",
    "wait.moment": "ਕੁਝ ਮਿੰਟ",
