    "consent.cardLink": "ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
    "consent.switchDetail":
      "Judge ਨੂੰ AI ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਤੁਹਾਡੇ ਨਾਂ-ਰਹਿਤ ਫ਼ੈਸਲੇ ਅਤੇ ਰੇਟਿੰਗਾਂ ਵਰਤਣ ਦਿੰਦਾ ਹੈ। ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਚਾਲੂ ਨਾ ਕਰੋ, ਬੰਦ ਰਹਿੰਦਾ ਹੈ।",
    "consent.sensitiveTitle": "ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ",
    "consent.sensitiveBody":
      "ਮੇਰੀ ਲਿਖਤ ਵਿੱਚ ਸਿਹਤ ਜਾਂ ਰਿਸ਼ਤਿਆਂ ਵਰਗੇ ਨਿੱਜੀ ਵੇਰਵੇ ਹੋ ਸਕਦੇ ਹਨ। Judge ਨਾਂ ਹਟਾ ਕੇ ਇਸ ਨੂੰ ਮੇਰਾ ਫ਼ੈਸਲਾ ਲਿਖਣ ਲਈ ਬਾਹਰੀ AI ਸੇਵਾ ਪ੍ਰਦਾਤਾ ਨੂੰ ਭੇਜਦਾ ਹੈ, ਅਤੇ ਮੇਰੇ ਹਟਾਉਣ ਤੱਕ ਰੱਖਦਾ ਹੈ।",
