    "deletePage.title": "ਆਪਣਾ Judge ਖਾਤਾ ਮਿਟਾਓ",
    "deletePage.lead": "Judge, Aytu Tuna ਦੀ ਐਪ ਹੈ। ਤੁਸੀਂ ਐਪ ਜਾਂ ਵੈੱਬਸਾਈਟ ਵਿੱਚ ਕਦੇ ਵੀ ਆਪ ਖਾਤਾ ਅਤੇ ਉਸ ਦਾ ਡੇਟਾ ਮਿਟਾ ਸਕਦੇ ਹੋ।",
    "deletePage.appTitle": "ਐਪ ਵਿੱਚ",
    "deletePage.app": "Judge ਖੋਲ੍ਹੋ, ਖਾਤੇ ਵਿੱਚ ਜਾਓ, ਖਾਤਾ ਮਿਟਾਓ ਉੱਤੇ ਟੈਪ ਕਰੋ ਅਤੇ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "deletePage.webTitle": "ਵੈੱਬਸਾਈਟ ਉੱਤੇ",
    "deletePage.web": "okjudge.com ਉੱਤੇ ਸਾਈਨ ਇਨ ਕਰੋ, ਖਾਤਾ ਖੋਲ੍ਹੋ, ਖਾਤਾ ਮਿਟਾਓ ਚੁਣੋ ਅਤੇ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "deletePage.billingTitle": "ਜੇ ਤੁਹਾਡੇ ਕੋਲ ਪਲਾਨ ਹੈ",
    "deletePage.billing": "ਖਾਤਾ ਮਿਟਾਉਣ ਨਾਲ App Store ਜਾਂ Google Play ਤੋਂ ਖਰੀਦਿਆ ਪਲਾਨ ਰੱਦ ਨਹੀਂ ਹੁੰਦਾ, ਅਤੇ ਸਟੋਰ ਤੁਹਾਡੇ ਤੋਂ ਪੈਸੇ ਕੱਟਦਾ ਰਹਿੰਦਾ ਹੈ। ਪਹਿਲਾਂ App Store ਜਾਂ Google Play ਦੀਆਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਇਸਨੂੰ ਰੱਦ ਕਰੋ।",
    "deletePage.removedTitle": "ਕੀ ਮਿਟਾਇਆ ਜਾਂਦਾ ਹੈ",
    "deletePage.removed":
      "ਤੁਹਾਡਾ ਖਾਤਾ, ਸਾਈਨ-ਇਨ ਰਿਕਾਰਡ, ਕ੍ਰੈਡਿਟ, ਪਲਾਨ ਅਤੇ ਵਰਤੋਂ ਦੀਆਂ ਘਟਨਾਵਾਂ ਮਿਟਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਤੁਹਾਡੇ ਫ਼ੈਸਲੇ ਅਤੇ ਕੇਸਾਂ ਵਿੱਚ ਤੁਹਾਡਾ ਪੱਖ ਹਟਾਇਆ ਜਾਂਦਾ ਹੈ: ਅਸਲ ਲਿਖਤ ਅਤੇ ਨਾਂ ਤੁਰੰਤ ਮਿਟਾਏ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਨਾਂ-ਰਹਿਤ ਲਿਖਤ ਤੇ ਫ਼ੈਸਲਾ 30 ਦਿਨ ਬਾਅਦ (ਕੇਸ ਵਿੱਚ, ਉਸ ਦੇ ਸਾਰੇ ਲੋਕਾਂ ਵੱਲੋਂ ਹਟਾਉਣ ਤੋਂ 30 ਦਿਨ ਬਾਅਦ)।",
    "deletePage.keptTitle": "ਅਸੀਂ ਕੀ ਰੱਖਦੇ ਹਾਂ",
    "deletePage.kept":
      "ਹਟਾਏ ਫ਼ੈਸਲਿਆਂ ਦਾ ਨਤੀਜਾ ਅਤੇ ਤਾਰੀਖਾਂ, ਬਿਨਾਂ ਲਿਖਤ ਅਤੇ ਨਾਵਾਂ ਦੇ। ਤੁਹਾਡੀਆਂ ਰੇਟਿੰਗਾਂ, ਜੋ ਬੇਤਰਤੀਬ ID ਉੱਤੇ ਭੇਜ ਦਿੱਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਤਾਂ ਜੋ ਉਹ ਤੁਹਾਡੇ ਤੱਕ ਨਾ ਪਹੁੰਚਣ। ਤੁਹਾਡੀਆਂ ਸਹਿਮਤੀ ਦੇ ਰਿਕਾਰਡ 6 ਸਾਲ, ਤੁਹਾਡੇ ਨਾਲ ਕਿਸੇ ਲਿੰਕ ਤੋਂ ਬਿਨਾਂ। ਤੁਹਾਡੇ ਖਾਤੇ ਤੋਂ ਬਿਨਾਂ ਡਿਵਾਈਸ ਰਿਕਾਰਡ, ਵੱਧ ਤੋਂ ਵੱਧ 180 ਦਿਨ। ਜੋ ਹਟਾਇਆ ਗਿਆ ਉਸ ਦੀ ਸੂਚੀ, ID ਅਤੇ ਤਾਰੀਖ਼ਾਂ ਸਮੇਤ ਪਰ ਲਿਖਤ ਤੋਂ ਬਿਨਾਂ, 90 ਦਿਨ। ਮੁਫ਼ਤ ਕ੍ਰੈਡਿਟ ਦੀ ਵਾਰ-ਵਾਰ ਦੁਰਵਰਤੋਂ ਰੋਕਣ ਲਈ ਤੁਹਾਡੀ ਈਮੇਲ ਦਾ ਕੋਡ ਕੀਤਾ ਰੂਪ। ਬੈਕਅੱਪ ਵਿੱਚ ਪੁਰਾਣੀਆਂ ਕਾਪੀਆਂ ਵੱਧ ਤੋਂ ਵੱਧ 14 ਦਿਨ ਰਹਿੰਦੀਆਂ ਹਨ।",
