    "appeal.bySelf": "ਤੁਹਾਡੇ ਨਵੇਂ ਵੇਰਵੇ ਤੋਂ ਬਾਅਦ",
    "appeal.generic.upheld": "ਨਵੇਂ ਵੇਰਵੇ ਨਾਲ ਨਤੀਜਾ ਨਹੀਂ ਬਦਲਿਆ।",
    "appeal.generic.overturned": "ਨਵੇਂ ਵੇਰਵੇ ਨੇ ਨਤੀਜਾ ਪਲਟ ਦਿੱਤਾ।",
    "appeal.generic.changed": "ਨਵੇਂ ਵੇਰਵੇ ਨੇ ਫ਼ੈਸਲਾ ਬਦਲ ਦਿੱਤਾ।",
    "appeal.previous": "ਪਹਿਲਾਂ ਵਾਲਾ ਫ਼ੈਸਲਾ",
    "appeal.failed": "ਦੁਬਾਰਾ ਫ਼ੈਸਲਾ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਤੁਹਾਡਾ ਕ੍ਰੈਡਿਟ ਵਾਪਸ ਆ ਗਿਆ ਹੈ; ਤੁਸੀਂ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ।",
    "appeal.refused": "ਜੱਜਾਂ ਨੇ ਉਸ ਵੇਰਵੇ ਨਾਲ ਦੁਬਾਰਾ ਫ਼ੈਸਲਾ ਕਰਨ ਤੋਂ ਨਾਂਹ ਕਰ ਦਿੱਤੀ। ਤੁਹਾਡਾ ਕ੍ਰੈਡਿਟ ਵਾਪਸ ਆ ਗਿਆ ਹੈ।",
    "appeal.history": "ਫ਼ੈਸਲੇ ਦਾ ਇਤਿਹਾਸ",
    "faq.both.q": "ਕੀ ਦੂਜੀ ਧਿਰ ਵੀ ਆਪਣਾ ਪੱਖ ਦੱਸ ਸਕਦੀ ਹੈ?",
    "faq.both.a":
      "ਹਾਂ, ਤੁਹਾਡੇ ਸਾਈਨ ਇਨ ਕਰਨ ਤੋਂ ਬਾਅਦ। “ਦੋਵੇਂ ਪੱਖ” ਚੁਣੋ ਅਤੇ ਤੁਹਾਨੂੰ ਉਨ੍ਹਾਂ ਨੂੰ ਭੇਜਣ ਲਈ ਇੱਕ ਨਿੱਜੀ ਲਿੰਕ ਮਿਲੇਗਾ। ਉਹ ਬਿਨਾਂ ਖਾਤੇ ਦੇ ਆਪਣਾ ਪੱਖ ਲਿਖਦੇ ਹਨ, ਅਤੇ ਫ਼ੈਸਲੇ ਤੱਕ ਤੁਹਾਡੇ ਵਿੱਚੋਂ ਕੋਈ ਵੀ ਦੂਜੇ ਦੀ ਲਿਖਤ ਨਹੀਂ ਦੇਖਦਾ। ਤੁਸੀਂ ਕਦੇ ਵੀ ਸਿਰਫ਼ ਆਪਣੇ ਪੱਖ ’ਤੇ ਫ਼ੈਸਲਾ ਲੈ ਸਕਦੇ ਹੋ, ਅਤੇ ਲਿੰਕ 7 ਦਿਨਾਂ ਬਾਅਦ ਕੰਮ ਕਰਨਾ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ।",
    "faq.both.premium":
      "ਕੇਸ ’ਤੇ 1 ਫ਼ੈਸਲਾ ਲੱਗਦਾ ਹੈ, ਜੋ ਉਨ੍ਹਾਂ ਦੇ ਜਵਾਬ ਨਾ ਦੇਣ ’ਤੇ ਵਾਪਸ ਮਿਲ ਜਾਂਦਾ ਹੈ। ਫ਼ੈਸਲੇ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ ਵਿੱਚੋਂ ਹਰ ਕੋਈ ਇੱਕ ਵਾਰ ਵੇਰਵਾ ਜੋੜ ਕੇ ਦੁਬਾਰਾ ਫ਼ੈਸਲਾ ਕਰਵਾ ਸਕਦਾ ਹੈ (1 ਫ਼ੈਸਲਾ)।",
    "faq.evidence.q": "ਕੀ ਸਕ੍ਰੀਨਸ਼ਾਟ ਵੀ ਜੋੜੇ ਜਾ ਸਕਦੇ ਹਨ?",
    "faq.evidence.a":
      "ਹਾਂ, ਹਰ ਪੱਖ ਵੱਲੋਂ ਵੱਧ ਤੋਂ ਵੱਧ ਤਿੰਨ, ਜਿਵੇਂ ਕੋਈ ਚੈਟ ਜਾਂ ਰਸੀਦ। ਹਰ ਤਸਵੀਰ ਇੱਕ ਵਾਰ ਬਾਹਰੀ AI ਸੇਵਾ ਕੋਲ ਜਾਂਦੀ ਹੈ ਤਾਂ ਜੋ ਉਸ ਦੀ ਲਿਖਤ ਪੜ੍ਹੀ ਜਾ ਸਕੇ। ਜੱਜ ਉਹ ਰੂਪ ਦੇਖਦੇ ਹਨ ਜਿਸ ਵਿੱਚ ਨਾਂ ਲੁਕੇ ਹੋਣ। ਤਸਵੀਰ ਵਿੱਚੋਂ ਪੜ੍ਹੀ ਲਿਖਤ ਅਸੀਂ ਇਨਕ੍ਰਿਪਟ ਕਰਕੇ ਤੁਹਾਡੀ ਅਸਲ ਲਿਖਤ ਨਾਲ ਰੱਖਦੇ ਹਾਂ; ਤਸਵੀਰ ਆਪ ਕਦੇ ਸਟੋਰ ਨਹੀਂ ਹੁੰਦੀ। ਸਕ੍ਰੀਨਸ਼ਾਟ ਕੱਟੇ ਹੋਏ ਜਾਂ ਪ੍ਰਸੰਗ ਤੋਂ ਬਾਹਰ ਹੋ ਸਕਦੇ ਹਨ, ਇਸ ਲਈ ਜੱਜ ਉਨ੍ਹਾਂ ਨੂੰ ਤਕੜਾ ਸਬੂਤ ਮੰਨਦੇ ਹਨ, ਪੱਕਾ ਸਬੂਤ ਨਹੀਂ।",
    "about.casesTitle": "ਦੋਵਾਂ ਪੱਖਾਂ ਦੀ ਸੁਣਵਾਈ",
    "about.cases1":
      "ਦੋ-ਪੱਖੀ ਕੇਸ: ਸਾਈਨ ਇਨ ਕਰੋ, ਆਪਣਾ ਪੱਖ ਲਿਖੋ ਅਤੇ ਇੱਕ ਨਿੱਜੀ ਲਿੰਕ ਭੇਜੋ। ਦੂਜੀ ਧਿਰ ਤੁਹਾਡਾ ਪੱਖ ਦੇਖੇ ਬਿਨਾਂ ਆਪਣਾ ਲਿਖਦੀ ਹੈ, ਅਤੇ ਜੱਜ ਦੋਵਾਂ ਬਿਆਨਾਂ ਨੂੰ ਤੋਲਦੇ ਹਨ: ਕਿਸ ਗੱਲ ’ਤੇ ਸਹਿਮਤੀ ਹੈ, ਕਿਸ ’ਤੇ ਝਗੜਾ ਹੈ, ਅਤੇ ਕਿਹੜਾ ਸਬੂਤ ਫ਼ੈਸਲਾ ਬਦਲ ਸਕਦਾ ਹੈ।",
    "about.cases2": "ਜੇ 7 ਦਿਨਾਂ ਵਿੱਚ ਕੋਈ ਜਵਾਬ ਨਾ ਆਵੇ, ਤਾਂ ਲਿੰਕ ਕੰਮ ਕਰਨਾ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ। ਤੁਸੀਂ ਫਿਰ ਵੀ ਸਿਰਫ਼ ਆਪਣੇ ਪੱਖ ’ਤੇ ਫ਼ੈਸਲਾ ਲੈ ਸਕਦੇ ਹੋ।",
    "about.premiumTitle": "ਹੋਰ ਸਹੂਲਤਾਂ",
    "about.premium2": "ਸਬੂਤ: ਚੈਟਾਂ ਜਾਂ ਦਸਤਾਵੇਜ਼ਾਂ ਦੇ ਸਕ੍ਰੀਨਸ਼ਾਟ ਜੋੜੋ। ਅਸੀਂ ਉਨ੍ਹਾਂ ਵਿਚਲੀ ਲਿਖਤ ਪੜ੍ਹਦੇ ਹਾਂ, ਨਾਂ ਲੁਕਾਉਂਦੇ ਹਾਂ ਅਤੇ ਤਸਵੀਰ ਸੁੱਟ ਦਿੰਦੇ ਹਾਂ।",
    "about.premium3":
      "ਅਪੀਲ: ਫ਼ੈਸਲੇ ਤੋਂ ਬਾਅਦ ਹਰ ਕੋਈ ਇੱਕ ਵਾਰ ਵੇਰਵਾ ਜੋੜ ਸਕਦਾ ਹੈ। ਜੱਜ ਸਾਰਾ ਕੁਝ ਦੁਬਾਰਾ ਦੇਖਦੇ ਹਨ ਅਤੇ ਦੱਸਦੇ ਹਨ ਕਿ ਫ਼ੈਸਲਾ ਕਾਇਮ ਰਿਹਾ, ਪਲਟ ਗਿਆ ਜਾਂ ਬਦਲ ਗਿਆ। ਪਹਿਲਾਂ ਵਾਲੇ ਫ਼ੈਸਲੇ ਦੇਖੇ ਜਾ ਸਕਦੇ ਹਨ।",
    "about.premium4":
      "ਦੋ-ਪੱਖੀ ਕੇਸ ’ਤੇ 1 ਫ਼ੈਸਲਾ ਲੱਗਦਾ ਹੈ। ਲਿੰਕ ਭੇਜਣ ’ਤੇ ਇਹ ਰਾਖਵਾਂ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਜੇ 7 ਦਿਨਾਂ ਵਿੱਚ ਕੋਈ ਜਵਾਬ ਨਾ ਆਵੇ ਤਾਂ ਵਾਪਸ ਮਿਲ ਜਾਂਦਾ ਹੈ।",
    "pricing.premium.f5": "ਸਬੂਤ ਵਜੋਂ ਸਕ੍ਰੀਨਸ਼ਾਟ, ਪੜ੍ਹਨ ਤੋਂ ਬਾਅਦ ਸੁੱਟ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ, ਕੋਈ ਵਾਧੂ ਖ਼ਰਚਾ ਨਹੀਂ",
    "pricing.premium.f6": "ਫ਼ੈਸਲੇ ਤੋਂ ਬਾਅਦ ਵੇਰਵਾ ਜੋੜੋ ਅਤੇ ਦੁਬਾਰਾ ਫ਼ੈਸਲਾ ਕਰਵਾਓ (1 ਫ਼ੈਸਲਾ)",
    "pricing.premium.f7": "ਦੋਵੇਂ ਪੱਖ ਸੁਣੋ: ਦੂਜੀ ਧਿਰ ਨੂੰ ਆਪਣਾ ਪੱਖ ਦੱਸਣ ਲਈ ਨਿੱਜੀ ਲਿੰਕ ਭੇਜੋ",
