    "verdict.remove": "ਇਹ ਫ਼ੈਸਲਾ ਹਟਾਓ",
    "verdict.remove.confirm":
      "ਤੁਹਾਡੀ ਲਿਖਤ, ਨਾਂ ਅਤੇ ਦਿਖਣ ਵਾਲੇ ਨਾਂ ਹਟਾਉਣੇ ਹਨ? ਸਾਂਝਾ ਲਿੰਕ ਅਤੇ ਉਸ ਦੀ ਪ੍ਰੀਵਿਊ ਤਸਵੀਰ ਸਭ ਲਈ ਖੁੱਲ੍ਹਣੇ ਬੰਦ ਹੋ ਜਾਣਗੇ (ਚੈਟਾਂ ਵਿੱਚ ਪਹਿਲਾਂ ਹੀ ਭੇਜੇ ਪ੍ਰੀਵਿਊ ਉਦੋਂ ਤੱਕ ਦਿਖ ਸਕਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਉਹ ਐਪਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਤਾਜ਼ਾ ਨਹੀਂ ਕਰਦੀਆਂ)। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।",
