    "verdict.removeFailed": "ਇਸ ਵੇਲੇ ਹਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਿਆ। ਇੱਕ ਵਾਰ ਫਿਰ ਕੋਸ਼ਿਸ਼ ਕਰੋਗੇ?",
