    "parent.what": "Judge ਝਗੜੇ ਸੁਲਝਾਉਂਦਾ ਹੈ। ਤੁਸੀਂ ਕਿਸੇ ਵਿਵਾਦ ਬਾਰੇ ਦੱਸਦੇ ਹੋ, ਅਤੇ ਇੱਕ ਬਾਹਰੀ AI ਸੇਵਾ ਇਸ ਬਾਰੇ ਫ਼ੈਸਲਾ ਲਿਖਦੀ ਹੈ ਕਿ ਕਿਸ ਦਾ ਪੱਖ ਵਧੇਰੇ ਮਜ਼ਬੂਤ ਹੈ। ਹੋਰਾਂ ਨੂੰ ਆਪਣਾ ਪੱਖ ਦੱਸਣ ਲਈ ਸੱਦਿਆ ਜਾ ਸਕਦਾ ਹੈ।",
