    "parent.rule2": "ਉਨ੍ਹਾਂ ਦੀ ਲਿਖਤ ਨੂੰ ਸੇਵਾ ਸੁਧਾਰਨ ਲਈ ਕਦੇ ਨਹੀਂ ਵਰਤਦਾ",
